import{_ as l,o as r,c as t,a2 as s}from"./chunks/framework.ChIlRNAd.js";const m=JSON.parse('{"title":"Règles & libellés","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/rules.md","filePath":"fr/guide/rules.md"}'),a={name:"fr/guide/rules.md"};function o(i,e,n,u,g,d){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="regles-libelles" tabindex="-1">Règles &amp; libellés <a class="header-anchor" href="#regles-libelles" aria-label="Permalink to &quot;Règles &amp; libellés&quot;">​</a></h1><p>La page <strong>Règles &amp; libellés</strong> (<code>/rules</code>) automatise le tri de votre boîte : chaque règle applique une action aux mails qui lui correspondent. Elle a deux onglets : <strong>Règles</strong> et <strong>Libellés</strong> (<code>/rules?tab=labels</code>).</p><hr><h2 id="onglet-regles" tabindex="-1">Onglet Règles <a class="header-anchor" href="#onglet-regles" aria-label="Permalink to &quot;Onglet Règles&quot;">​</a></h2><p>La liste affiche pour chaque règle :</p><ul><li><strong>Nom</strong> ;</li><li><strong>Conditions</strong>, en clair (« de <a href="mailto:news@exemple.fr" target="_blank" rel="noreferrer">news@exemple.fr</a>, de plus de 30 jours ») ;</li><li><strong>Action</strong> (« Appliquer un libellé « Factures » »…) ;</li><li><strong>Dernière exécution</strong> (ou « Jamais exécutée ») ;</li><li><strong>Active</strong> : interrupteur pour suspendre ou réactiver la règle.</li></ul><p>Le menu <code>⋯</code> d&#39;une règle propose :</p><ul><li><strong>Exécuter</strong> : lance la règle tout de suite sur les mails déjà reçus. Un toast « Exécution de « … » » permet d&#39;<strong>Annuler</strong> pendant 10 s ; la suite se suit dans <a href="./activity.html">Activité</a>.</li><li><strong>Modifier</strong> : ouvre le formulaire.</li><li><strong>Supprimer</strong> : après confirmation (« La règle ne s&#39;exécutera plus. Les mails déjà traités restent tels quels. »).</li></ul><p>Sans règle, la page invite à en créer une ou à partir d&#39;un modèle de l&#39;onglet Libellés.</p><hr><h2 id="creer-une-regle" tabindex="-1">Créer une règle <a class="header-anchor" href="#creer-une-regle" aria-label="Permalink to &quot;Créer une règle&quot;">​</a></h2><p>Le bouton <strong>Nouvelle règle</strong> (aussi dans la palette <code>⌘K</code>) ouvre le formulaire. Il s&#39;ouvre aussi pré-rempli depuis :</p><ul><li><a href="./mails.html">Mails</a> : <strong>Créer une règle</strong> dans l&#39;en-tête (recherche courante), la barre de sélection ou le lecteur ;</li><li><a href="./cleanup.html">Nettoyage</a> et les suggestions de la <a href="./overview.html">Vue d&#39;ensemble</a> : <strong>Toujours faire ça</strong> ;</li><li>l&#39;onglet Libellés : <strong>Créer une règle</strong> sur un libellé.</li></ul><h3 id="champs" tabindex="-1">Champs <a class="header-anchor" href="#champs" aria-label="Permalink to &quot;Champs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Champ</th><th>Contenu</th></tr></thead><tbody><tr><td><strong>Nom</strong></td><td>proposé automatiquement (« Mails de … »)</td></tr><tr><td><strong>Quand un mail arrive de</strong></td><td>adresse ou domaine, par exemple <code>news@exemple.fr</code></td></tr><tr><td><strong>Autres conditions (conservées)</strong></td><td>conditions d&#39;une règle existante que le formulaire ne sait pas modifier ; elles sont gardées telles quelles</td></tr><tr><td><strong>Et qu&#39;il a plus de</strong></td><td>Aucune limite, 7 jours, 30 jours, 6 mois</td></tr><tr><td><strong>Alors</strong></td><td>Sauvegarder sur le NAS puis supprimer · Archiver (retirer de la boîte) · Supprimer · Appliquer un libellé (+ choix du <strong>Libellé</strong>)</td></tr><tr><td><strong>Exécution</strong></td><td>Manuelle, Quotidienne (par défaut), Hebdomadaire</td></tr><tr><td><strong>Appliquer aussi aux mails déjà reçus</strong></td><td>lance la règle dès l&#39;enregistrement (avec le même toast d&#39;annulation)</td></tr></tbody></table><p>Un expéditeur est obligatoire : « une règle basée sur la seule durée viserait toute la boîte ».</p><h3 id="apercu" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu" aria-label="Permalink to &quot;Aperçu&quot;">​</a></h3><p>Sous le formulaire, Nid calcule les mails concernés : « 143 mails concernés · 58 Mo », quelques <strong>Exemples</strong>, et le lien <strong>Voir les 143 mails</strong> qui ouvre <a href="./mails.html">Mails</a> avec la recherche correspondante.</p><p><strong>Créer la règle</strong> (ou <strong>Enregistrer</strong> en modification) valide.</p><hr><h2 id="onglet-libelles" tabindex="-1">Onglet Libellés <a class="header-anchor" href="#onglet-libelles" aria-label="Permalink to &quot;Onglet Libellés&quot;">​</a></h2><p>« Vos libellés Gmail, synchronisés avec leurs couleurs, et des modèles prêts à l&#39;emploi. »</p><h3 id="libelles-gmail" tabindex="-1">Libellés Gmail <a class="header-anchor" href="#libelles-gmail" aria-label="Permalink to &quot;Libellés Gmail&quot;">​</a></h3><p>L&#39;arbre des libellés du compte, avec leur couleur Gmail et le nombre de mails archivés. Les libellés imbriqués (<code>Factures/EDF</code>) sont affichés en arbre.</p><ul><li><strong>Nouveau libellé</strong> : crée le libellé dans Gmail. Utilisez « / » pour l&#39;imbriquer, par exemple <code>Factures/EDF</code>.</li><li>Menu d&#39;un libellé : <ul><li><strong>Renommer</strong> ;</li><li><strong>Couleur</strong> (palette Gmail : Rouge, Orange, Jaune, Vert, Turquoise, Bleu, Violet, Rose, Gris) ;</li><li><strong>Créer une règle</strong> qui applique ce libellé ;</li><li><strong>Voir les mails</strong> : ouvre <a href="./mails.html">Mails</a> filtré sur ce libellé ;</li><li><strong>Supprimer</strong> : après confirmation ; le libellé est retiré de Gmail et des mails qui le portent, les mails ne sont pas supprimés.</li></ul></li></ul><h3 id="categories-gmail" tabindex="-1">Catégories Gmail <a class="header-anchor" href="#categories-gmail" aria-label="Permalink to &quot;Catégories Gmail&quot;">​</a></h3><p>Promotions, Réseaux sociaux, Mises à jour, Forums : « Attribuées par Gmail, non modifiables. »</p><h3 id="modeles" tabindex="-1">Modèles <a class="header-anchor" href="#modeles" aria-label="Permalink to &quot;Modèles&quot;">​</a></h3><p>« Un clic crée le libellé Gmail et la règle qui le remplit. »</p><ul><li>Libellés : <strong>Factures</strong>, <strong>Livraisons</strong>, <strong>Banque</strong>, <strong>Billets &amp; voyages</strong> — chaque modèle crée le libellé et une règle quotidienne qui l&#39;applique selon des mots-clés de l&#39;objet (bouton <strong>Créer le libellé et la règle</strong>).</li><li>Expiration : <strong>Codes OTP (expire après 1 jour)</strong>, <strong>Promotions (expire après 7 jours)</strong> — une règle qui supprime ces mails une fois l&#39;âge dépassé (bouton <strong>Activer</strong>). Ces modèles remplacent l&#39;ancienne page « Expiration des emails ».</li><li><strong>Autres modèles</strong> : nettoyage (notifications GitHub, newsletters non lues, promotions, réseaux sociaux), archivage (mails anciens, factures, gros mails) et organisation (marquer comme lus les vieux mails…), bouton <strong>Activer</strong>.</li></ul><p>Un modèle déjà utilisé affiche <strong>Déjà actif</strong> et le bouton <strong>Modifier la règle</strong>.</p>',31)])])}const p=l(a,[["render",o]]);export{m as __pageData,p as default};
